def load_docclass_templates(override_path: str | None = None) -> dict[str, str]:
    """Docclass templates to sync: MAILROOM_DOCLASS_PROMPTS JSON wins."""
    path = override_path or os.environ.get("MAILROOM_DOCLASS_PROMPTS")
    if path:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        if not isinstance(data, dict) or not all(isinstance(v, str) for v in data.values()):
            raise ValueError(f"{path}: expected a JSON object of version_key -> template")
        return data
    return dict(DOCLASS_PROMPT_VERSIONS)
